func TestCopyVerifiedMediaCache(t *testing.T) {
	for _, name := range []string{"valid", "empty content", "unknown length", "empty path", "missing", "directory", "no fingerprint", "short fingerprint", "hash mismatch", "length mismatch", "oversized", "oversized declaration"} {
		t.Run(name, func(t *testing.T) {
			dir := t.TempDir()
			content := []byte("verified plaintext media")
			if name == "empty content" {
				content = nil
			}
			hash := sha256.Sum256(content)
			source, target := filepath.Join(dir, "source"), filepath.Join(dir, "target")
			if err := os.WriteFile(source, content, 0600); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(target, []byte("keep original"), 0600); err != nil {
				t.Fatal(err)
			}
			info := store.MediaDownloadInfo{LocalPath: source, FileSHA256: hash[:], FileLength: uint64(len(content))}
			wantHit := name == "valid" || name == "unknown length" || name == "empty content"
			switch name {
			case "unknown length":
				info.FileLength = 0
			case "empty path":
				info.LocalPath = ""
			case "missing":
				info.LocalPath = filepath.Join(dir, "missing")
			case "directory":
				info.LocalPath = dir
			case "no fingerprint":
				info.FileSHA256 = nil
			case "short fingerprint":
				info.FileSHA256 = hash[:5]
			case "hash mismatch":
				info.FileSHA256 = make([]byte, sha256.Size)
			case "length mismatch":
				info.FileLength++
			case "oversized":
				if err := os.Truncate(source, wa.MaxMediaDownloadSize+1); err != nil {
					t.Fatal(err)
				}
			case "oversized declaration":
				info.FileLength = wa.MaxMediaDownloadSize + 1
			}
			n, hit, err := CopyVerifiedMediaCache(context.Background(), info, target)
			if err != nil || hit != wantHit {
				t.Fatalf("copy = %d, %v, %v; want hit %v", n, hit, err, wantHit)
			}
			want := "keep original"
			if wantHit {
				want = string(content)
				if n != int64(len(content)) {
					t.Fatalf("bytes = %d", n)
				}
			} else if n != 0 {
				t.Fatalf("miss bytes = %d", n)
			}
			got, err := os.ReadFile(target)
			if err != nil || string(got) != want {
				t.Fatalf("target = %q, %v; want %q", got, err, want)
			}
			entries, err := os.ReadDir(dir)
			if err != nil {
				t.Fatal(err)
			}
			if len(entries) != 2 {
				t.Fatalf("temporary file leaked: %v", entries)
			}
			if wantHit {
				st, err := os.Stat(target)
				if err != nil {
					t.Fatal(err)
				}
				if st.Mode().Perm() != 0600 {
					t.Fatalf("target permissions = %o", st.Mode().Perm())
				}
			}
		})
	}
}

func TestCopyVerifiedMediaCacheSameFile(t *testing.T) {
	for _, hardlink := range []bool{false, true} {
		t.Run(map[bool]string{false: "same path", true: "hardlink"}[hardlink], func(t *testing.T) {
			dir := t.TempDir()
			content := []byte("must never truncate")
			hash := sha256.Sum256(content)
			source := filepath.Join(dir, "source")
			if err := os.WriteFile(source, content, 0600); err != nil {
				t.Fatal(err)
			}
			target := source
			if hardlink {
				target = filepath.Join(dir, "linked")
				if err := os.Link(source, target); err != nil {
					t.Fatal(err)
				}
			}
			info := store.MediaDownloadInfo{LocalPath: source, FileSHA256: hash[:], FileLength: uint64(len(content))}
			n, hit, err := CopyVerifiedMediaCache(context.Background(), info, target)
			if err != nil || !hit || n != int64(len(content)) {
				t.Fatalf("copy = %d, %v, %v", n, hit, err)
			}
			info.FileSHA256 = make([]byte, sha256.Size)
			_, hit, err = CopyVerifiedMediaCache(context.Background(), info, target)
			if err != nil || hit {
				t.Fatalf("corrupt same-file copy = %v, %v", hit, err)
			}
			got, err := os.ReadFile(source)
			if err != nil || string(got) != string(content) {
				t.Fatalf("source = %q, %v", got, err)
			}
		})
	}
}

func TestCopyVerifiedMediaCacheErrorsPreserveTarget(t *testing.T) {
	dir := t.TempDir()
	content := []byte("verified plaintext")
	hash := sha256.Sum256(content)
	source, target := filepath.Join(dir, "source"), filepath.Join(dir, "target")
	if err := os.WriteFile(source, content, 0600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(target, []byte("keep original"), 0600); err != nil {
		t.Fatal(err)
	}
	info := store.MediaDownloadInfo{LocalPath: source, FileSHA256: hash[:]}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, hit, err := CopyVerifiedMediaCache(ctx, info, target); hit || !errors.Is(err, context.Canceled) {
		t.Fatalf("canceled copy = %v, %v", hit, err)
	}
	if _, hit, err := CopyVerifiedMediaCache(context.Background(), info, filepath.Join(source, "target")); hit || err == nil {
		t.Fatalf("destination error = %v, %v", hit, err)
	}
	if _, hit, err := CopyVerifiedMediaCache(context.Background(), info, dir); hit || err == nil {
		t.Fatalf("rename error = %v, %v", hit, err)
	}
	got, err := os.ReadFile(target)
	if err != nil || string(got) != "keep original" {
		t.Fatalf("target = %q, %v", got, err)
	}
	entries, err := os.ReadDir(dir)
	if err != nil || len(entries) != 2 {
		t.Fatalf("temporary file leaked: %v, %v", entries, err)
	}
}

func TestCopyVerifiedMediaCacheCreatesOutputDirectoryOnlyAfterVerification(t *testing.T) {
	dir := t.TempDir()
	content := []byte("verified nested output")
	hash := sha256.Sum256(content)
	source := filepath.Join(dir, "source")
	if err := os.WriteFile(source, content, 0600); err != nil {
		t.Fatal(err)
	}
	info := store.MediaDownloadInfo{LocalPath: source, FileSHA256: make([]byte, sha256.Size)}
	target := filepath.Join(dir, "nested", "output", "target")
	if n, hit, err := CopyVerifiedMediaCache(context.Background(), info, target); err != nil || hit || n != 0 {
		t.Fatalf("invalid cache copy = %d, %v, %v", n, hit, err)
	}
	if _, err := os.Stat(filepath.Join(dir, "nested")); !os.IsNotExist(err) {
		t.Fatalf("invalid cache created output directory: %v", err)
	}
	info.FileSHA256 = hash[:]
	if n, hit, err := CopyVerifiedMediaCache(context.Background(), info, target); err != nil || !hit || n != int64(len(content)) {
		t.Fatalf("valid nested copy = %d, %v, %v", n, hit, err)
	}
	got, err := os.ReadFile(target)
	if err != nil || string(got) != string(content) {
		t.Fatalf("nested output = %q, %v", got, err)
	}
}

package main

import (
	"context"
	"errors"
	"fmt"
	"testing"

	"go.mau.fi/whatsmeow"
	waProto "go.mau.fi/whatsmeow/binary/proto"
	"go.mau.fi/whatsmeow/types"
)

// retryReviewSender models the network boundary, not a real WhatsApp account.
// In the post-dispatch case the frame has left before confirmation is lost.
// The concrete library reconnect/socket-loss branch can return ErrNotConnected
// at that point. Every subsequent call represents a fresh SendMessage request.
type retryReviewSender struct {
	recordingTextSender
	firstErr       error
	beforeDispatch bool
	calls          int
	frames         []types.MessageID
}

func (s *retryReviewSender) send() (types.MessageID, error) {
	s.calls++
	if s.calls == 1 && s.beforeDispatch {
		return "", s.firstErr
	}
	id := types.MessageID(fmt.Sprintf("synthetic-message-%d", s.calls))
	s.frames = append(s.frames, id)
	if s.calls == 1 && s.firstErr != nil {
		return "", s.firstErr
	}
	return id, nil
}

func (s *retryReviewSender) SendText(context.Context, types.JID, string) (types.MessageID, error) {
	return s.send()
}

func (s *retryReviewSender) SendProtoMessage(context.Context, types.JID, *waProto.Message) (types.MessageID, error) {
	return s.send()
}

// runRetryReview uses the actual production outer retry and text construction
// paths. Only the connection/sender boundary is fake; all data is synthetic.
func runRetryReview(t *testing.T, sender *retryReviewSender) (types.MessageID, error, int) {
	t.Helper()
	db := openSendTestDB(t)
	reconnects := 0
	id, err := runSendOperation(context.Background(), func(context.Context) error {
		reconnects++
		return nil
	}, func(ctx context.Context) (types.MessageID, error) {
		return sendTextMessageWithSender(ctx, sender, db,
			types.JID{User: "15551110000", Server: types.DefaultUserServer},
			"synthetic retry boundary probe", "", "", nil, nil,
			textEphemeralOptions{}, textSendOptions{allowSelf: true})
	})
	return id, err, reconnects
}

func TestSendRetryUncertaintyControls(t *testing.T) {
	// Controls distinguish a safe preparation retry from lost acknowledgement.
	// A prior frame plus a terminal outcome must not create another frame.
	cases := []struct {
		name                      string
		err                       error
		before                    bool
		calls, frames, reconnects int
		wantErr                   bool
	}{
		{"success", nil, false, 1, 1, 0, false},
		{"lookup_timeout_before_dispatch", whatsmeow.ErrIQTimedOut, true, 2, 1, 1, false},
		// The same unqualified error can occur before or after dispatch, so
		// conservatively leave either outcome to the caller without a new send.
		{"disconnected_before_dispatch", whatsmeow.ErrNotConnected, true, 1, 0, 0, true},
		{"wrapped_disconnected_after_dispatch", fmt.Errorf("message response: %w", whatsmeow.ErrNotConnected), false, 1, 1, 0, true},
		{"message_ack_timeout", whatsmeow.ErrMessageTimedOut, false, 1, 1, 0, true},
		{"wrapped_message_ack_timeout", fmt.Errorf("message response: %w", whatsmeow.ErrMessageTimedOut), false, 1, 1, 0, true},
		{"cancellation_after_dispatch", context.Canceled, false, 1, 1, 0, true},
		{"deadline_after_dispatch", context.DeadlineExceeded, false, 1, 1, 0, true},
		{"server_rejection", errors.New("server returned error 500"), false, 1, 1, 0, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			s := &retryReviewSender{firstErr: tc.err, beforeDispatch: tc.before}
			_, err, reconnects := runRetryReview(t, s)
			if (err != nil) != tc.wantErr || s.calls != tc.calls || len(s.frames) != tc.frames || reconnects != tc.reconnects {
				t.Fatalf("err=%v calls=%d frames=%v reconnects=%d", err, s.calls, s.frames, reconnects)
			}
			t.Logf("calls=%d frames=%v reconnects=%d error=%v", s.calls, s.frames, reconnects, err)
		})
	}
}

func TestSendRetryPostDispatchDisconnectDoesNotStartFreshSend(t *testing.T) {
	// This regression states the required boundary:
	// no fresh message after an error compatible with prior transmission.
	// It does not claim that a live recipient received two messages.
	s := &retryReviewSender{firstErr: whatsmeow.ErrNotConnected}
	id, err, reconnects := runRetryReview(t, s)
	if len(s.frames) != 1 || s.calls != 1 || reconnects != 0 || err == nil || id != "" {
		t.Fatalf("post-dispatch uncertainty started a fresh send: frames=%v calls=%d reconnects=%d result_id=%s error=%v", s.frames, s.calls, reconnects, id, err)
	}
}

